Let $ i,j $ be distinct opinions. 
  Consider the stopping times $\tau^{\mathrm{weak}}_i,\tau^{\mathrm{weak}}_j,\tau^{+}_\delta,\tau^{+}_\eta$ defined in 4.4, 5.3 and let $c^{\mathrm{weak}}=1/10$.
  Suppose that
  \begin{align*}
    \gamma_0 \ge \begin{cases}
      c_0 \sqrt{\frac{\log n}{n}}	& \text{for 3-Majority},\\
      \frac{c_0(\log n)^2}{n} & \text{for 2-Choices}
    \end{cases}
  \end{align*}
  for a sufficiently large constant $c_0>0$.

  Then, for any constant $ c_{*}>0 $, there exists a large constant $ C>0 $ such that the following holds
  for $ x_{\delta} = x_{\eta} = c_{*}\sqrt{\frac{\log n}{n}}$.
  \begin{enumerate}

  \item For 3-Majority, we have
  \begin{align*} 
    \Pr\qty[ \min\qty{ \tau^{+}_\delta, \tau^{\mathrm{weak}}_i,\tau^{\mathrm{weak}}_j } > \frac{C\log n}{\gamma_0} ] \le O(n^{-10}).
  \end{align*}
  \item For 2-Choices, we have
  \begin{align*}
    \Pr\qty[ \min\qty{ \tau^{+}_\eta, \tau^{\mathrm{weak}}_i,\tau^{\mathrm{weak}}_j } > \frac{C\log n}{\gamma_0} ] \le O(n^{-10}).
  \end{align*}
  \end{enumerate}

Let $ i,j $ be distinct opinions that are not weak at round $ 0 $.
  Consider the stopping times $\tau^{\mathrm{weak}}_i,\tau^{\mathrm{weak}}_j, \tau^{+}_\delta, \tau^{+}_\eta $ defined in 4.4, 5.3 and let $c^{\mathrm{weak}}=1/10$.








  Then, we have the following:
\begin{enumerate}

  \item For 3-Majority, 
  let $x_{\delta}=\frac{1}{1000\sqrt{n}}$ and 
  suppose $\gamma_0=\Omega\qty(\sqrt{\frac{\log n}{n}})$.
  Then, there is a positive constant $c \in (0,1)$ such that
  \begin{align*} 
    \Pr\qty[ \min\qty{ \tau^{+}_\delta,\tau^{\mathrm{weak}}_i,\tau^{\mathrm{weak}}_j } > \frac{1}{\gamma_0}] \le 1-c.
  \end{align*}
  \item For 2-Choices, 
  let 


  $x_{\eta}=\frac{1}{2000\sqrt{\mathrm{e} n}}$ and 
  suppose $\gamma_0\geq \frac{C(\log n)^2}{n}$ for a sufficiently large constant $C>0$.

  Then, there is a  positive constant $c \in (0,1)$ such that
  \begin{align*} 
    \Pr\qty[ \min\qty{ \tau^{+}_\eta,\tau^{\mathrm{weak}}_i,\tau^{\mathrm{weak}}_j} > \frac{1}{\gamma_0} ] \le 1-c.
  \end{align*}
  \end{enumerate}

Let $ i,j $ be distinct opinions that are not weak at round $ 0 $ and $ \alpha_0(i) \ge \alpha_0(j) $.
  Consider the stopping times $\tau^{\mathrm{weak}}_j,\tau^{\uparrow}_\delta, \tau^{\uparrow}_\eta$ defined in 5.3, 4.4
  and let $c^{\mathrm{weak}}=1/10, c^{\uparrow}_\delta=1/20, c^\uparrow_\eta=1/1000$.
  Then, we have the following:
\begin{enumerate}

  \item For 3-Majority,
  \begin{align*} 
     \Pr\qty[ \min\qty{ \tau^{\uparrow}_\delta,\tau^{\mathrm{weak}}_j } >  \frac{1}{\gamma_0} ] \le \exp\qty(-\Omega\qty(n\gamma_0^2)) + \exp\qty(-\Omega\qty(n\delta_0(i,j)^2)). 
  \end{align*}
  \item For 2-Choices,
  \begin{align*} 
    \Pr\qty[ \min\qty{ \tau^{\uparrow}_\eta,\tau^{\mathrm{weak}}_j } >  \frac{1}{\gamma_0} ] \le  \exp\qty(-\Omega\qty(n\gamma_0)) + \exp\qty(-\Omega\qty( n\eta_0(i,j)^2 )).
  \end{align*}
\end{enumerate}

Consider stopping times defined in 4.4.
  Fix two distinct opinions $i,j\in [k]$.
  Then, we have the following:
  \begin{enumerate}

\item 
For any constant $\varepsilon\in (0,1)$, 
let $C_{\mbox{\tiny4.5(item:tauiup)}}\mathrel{\mathop:}= \frac{ (1 - \varepsilon) c_\alpha^{\uparrow} }{(1+c_\alpha^{\uparrow})^2}$.
Then, we have
\begin{align*}
\Pr\qty[ \tau^{\uparrow}_i \le \frac{C_{\mbox{\tiny4.5(item:tauiup)}}}{ \alpha_0(i)} ] \le 
    \begin{cases}
        \exp\qty(-\Omega\qty( n\alpha_0(i)^2 ))	& \text{for 3-Majority},\\[10pt]
        \exp\qty( -\Omega\qty( n\alpha_0(i) ) ) & \text{for 2-Choices}.
    \end{cases}
\end{align*}
\item 
For any constant $\varepsilon \in (0,1)$, let
$C_{\mbox{\tiny4.5(item:tauidown)}}\mathrel{\mathop:}= \frac{(1-c^{\mathrm{weak}})(1-\varepsilon)c^{\downarrow}_\alpha}{c^{\mathrm{weak}} (1+c_\alpha^{\uparrow})^2}$.
Then, we have
\begin{align*}
    \Pr\qty[ \tau^{\downarrow}_i \le \min\left\lbrace \tau^{\mathrm{weak}}_i,\tau^{\uparrow}_i,\frac{C_{\mbox{\tiny4.5(item:tauidown)}}}{\alpha_0(i)} \right\rbrace ] \le 
    \begin{cases}
            \exp\qty(-\Omega\qty( n\alpha_0(i)^2 ))	& \text{for 3-Majority},\\[10pt]
            \exp\qty( -\Omega\qty( n\alpha_0(i) ) ) & \text{for 2-Choices}.
    \end{cases}
\end{align*}
\item 


For any $T>0$, we have
\begin{align*}
    \Pr\qty[\tau^{\mathrm{active}}_i\leq \min\{T,\tau^{\downarrow}_\gamma\}]
    \leq 
    \begin{cases}
      \exp\qty(-\Omega\qty(\frac{n\gamma_0}{T})) & \text{for 3-Majority}, \\[10pt]
      \exp\qty(-\Omega\qty(\frac{n\gamma_0}{T\gamma_0+1})) & \text{for 2-Choices}.
    \end{cases}
\end{align*}
\item 
        For any $T> 0$, we have
    \begin{align*}
         \Pr\qty[ \tau^{\downarrow}_\delta \le \min\{\tau^{\mathrm{weak}}_j,\tau^{\uparrow}_i,T\} ] \le
         \begin{cases}
           \exp\qty( -\Omega\qty( \frac{n\delta_0(i,j)^2}{\alpha_0(i)T+\delta_0(i,j)} ) ) & \text{for 3-Majority}, \\[10pt]
           \exp\qty( -\Omega\qty(\frac{n \delta_0(i,j)^2}{\alpha_0(i)^2 T+\delta_0(i,j)}) )	&  \text{for 2-Choices}.
         \end{cases}
    \end{align*}
    \item 
    For any constant $\varepsilon\in (0,1)$,
    let $C_{\mbox{\tiny4.5(item:taudeltaup)}}\mathrel{\mathop:}= \frac{(1-c^{\mathrm{weak}})(1+\varepsilon)c^{\uparrow}_\delta}{(1-2c^{\mathrm{weak}})(1-c^{\downarrow}_\alpha)(1-c^{\downarrow}_\delta)}$.
    Then, we have
    \begin{align*} 
         \Pr\qty[ \min\left\lbrace  \tau^{\uparrow}_\delta, \tau^{\mathrm{weak}}_j, \tau^{\downarrow}_\delta,  \tau^{\uparrow}_i, \tau^{\downarrow}_i  \right\rbrace > \frac{C_{\mbox{\tiny4.5(item:taudeltaup)}}}{\alpha_0(i)}]
         \leq 
         \begin{cases}
          \exp\qty(-\Omega(n\delta_0(i,j)^2)) & \text{for 3-Majority}, \\[10pt]
          \exp\qty(-\Omega\qty(\frac{n\delta_0(i,j)^2}{\alpha_0(i)}))	& \text{for 2-Choices}.
         \end{cases}
    \end{align*}
    \item 
    For any $T>0$, we have
    \begin{align*}
        \Pr\qty[\tau^{\downarrow}_\gamma\leq \min\left\lbrace T,\tau^{\uparrow}_\gamma \right\rbrace]\le
          \begin{cases}
          \exp\qty(-\Omega\qty(\frac{n\sqrt{\gamma_0}}{T})) & \text{for 3-Majority}, \\[10pt]
          \exp\qty(-\Omega\qty(\frac{n}{T+\gamma_0^{-1/2}})) & \text{for 2-Choices}.
        \end{cases}
    \end{align*}
\end{enumerate}
